/* * @lc app=leetcode id=2818 lang=kotlin * * [2818] Apply Operations to Maximize Score */ class Solution { fun maximumScore(nums: List<Int>, k: Int): Int = nums.map { x -> IntArray(1) { x }.let { v -> (2..100000).takeWhile { i -> i * i <= v[0] }.filter { i -> (v[0] % i == 0).also { if (it) generateSequence { if (v[0] % i == 0) (v[0] / i).also { v[0] = it } else null }.last() } }.size + if (v[0] > 1) 1 else 0 } }.let { scores -> IntArray(nums.size).also { left -> IntArray(nums.size) { nums.size }.also { right -> java.util.ArrayDeque<Int>().let { st -> nums.indices.forEach { i -> generateSequence { if (st.isNotEmpty() && scores[st.peek()] < scores[i]) st.pop() else null }.forEach { right[it] = i }.also { left[i] = st.peek() ?: -1 }.also { st.push(i) } } } } }.let { left -> IntArray(nums.size) { nums.size }.apply { java.util.ArrayDeque<Int>().let { st -> nums.indices.forEach { i -> generateSequence { if (st.isNotEmpty() && scores[st.peek()] < scores[i]) st.pop() else null }.forEach { this[it] = i }.also { st.push(i) } } } }.let { right -> LongArray(2) { if (it == 0) k.toLong() else 1L }.also { state -> nums.indices.sortedByDescending { nums[it] }.forEach { i -> minOf(state[0], (i.toLong() - left[i]) * (right[i] - i)).let { take -> (state[0] - take).also { state[0] = it }.also { state[1] = (state[1] * generateSequence(Triple(nums[i].toLong(), take, 1L)) { (b, e, a) -> if (e > 0) Triple((b * b) % 1000000007, e / 2, if (e % 2L == 1L) (a * b) % 1000000007 else a) else null }.last().third) % 1000000007 } } } }[1].toInt() } } } }